//! Vulnerable JavaScript libraries: the technologies detected with a version,
//! checked against the Retire.js vulnerability repository (Apache-2.0).
//!
//! The data is `data/retire.tsv`, regenerated by `scripts/update-retire.py`: one
//! row per known vulnerability with the affected range (`at_or_above` inclusive,
//! `below` exclusive), severity, identifiers and a short summary.

use std::cmp::Ordering;
use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

use crate::detect::Technology;
use crate::findings::finding;
use crate::report::{Finding, Severity};

pub(crate) const RETIRE: &str = include_str!("../../data/retire.tsv");

/// Detected technology names that do not match a Retire.js component after
/// normalization, and the component they stand for. Looked up before anything
/// else, so a name here never reaches the generic match: `Angular` (2 and
/// later) would otherwise match `angularjs`.
const ALIASES: &[(&str, &str)] = &[
    ("Angular", "@angular/core"),
    ("DataTables", "jquery.datatables"),
    ("Froala Editor", "froala"),
    ("prettyPhoto", "jquery.prettyPhoto"),
];

/// A vulnerable range of one library.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Vulnerability {
    component: &'static str,
    /// Inclusive; `None` when the range has no lower bound.
    at_or_above: Option<Version>,
    /// Exclusive.
    below: Version,
    severity: Severity,
    identifiers: Vec<&'static str>,
    /// Exact versions inside the range that are not affected (patched builds).
    excludes: Vec<&'static str>,
    summary: &'static str,
}

/// The source version for the report's `sources`, from the first line of the
/// data file: `RetireJS/retire.js@970fc88 (2026-10-30)`.
pub(crate) fn provenance() -> String {
    let first = RETIRE.lines().next().unwrap_or_default();
    first
        .split_once(" at ")
        .map(|(_, rest)| rest.trim_end_matches('.').to_owned())
        .unwrap_or_default()
}

struct Database {
    by_component: HashMap<&'static str, Vec<Vulnerability>>,
    /// Normalized component name to component.
    by_name: HashMap<String, &'static str>,
}

fn database() -> &'static Database {
    static DATABASE: OnceLock<Database> = OnceLock::new();
    DATABASE.get_or_init(|| {
        let mut by_component: HashMap<&'static str, Vec<Vulnerability>> = HashMap::new();
        for vulnerability in RETIRE.lines().filter(|l| !l.starts_with('#')).filter_map(parse_row) {
            by_component
                .entry(vulnerability.component)
                .or_default()
                .push(vulnerability);
        }
        let by_name = by_component.keys().map(|c| (normalize(c), *c)).collect();
        Database { by_component, by_name }
    })
}

fn parse_row(line: &'static str) -> Option<Vulnerability> {
    let mut fields = line.split('\t');
    let component = fields.next()?;
    let at_or_above = fields.next()?;
    let below = fields.next()?;
    let severity = Severity::parse(fields.next()?)?;
    let identifiers = fields.next()?;
    let excludes = fields.next()?;
    let summary = fields.next().unwrap_or_default();
    let list = |text: &'static str| text.split(',').filter(|s| !s.is_empty()).collect::<Vec<_>>();
    Some(Vulnerability {
        component,
        at_or_above: if at_or_above.is_empty() {
            None
        } else {
            Some(Version::parse(at_or_above)?)
        },
        below: Version::parse(below)?,
        severity,
        identifiers: list(identifiers),
        excludes: list(excludes),
        summary,
    })
}

/// Lowercase letters and digits only: `Moment.js` and `moment.js` meet.
fn normalize(name: &str) -> String {
    name.chars()
        .filter(char::is_ascii_alphanumeric)
        .map(|c| c.to_ascii_lowercase())
        .collect()
}

/// The Retire.js component for a detected technology, if there is one: an
/// alias, or a name that matches after normalization, with or without a `js`
/// suffix (`Vue.js` is `vue`, `Prototype` is `prototypejs`).
pub fn component_for(technology: &str) -> Option<&'static str> {
    if let Some((_, component)) = ALIASES.iter().find(|(name, _)| *name == technology) {
        return Some(component);
    }
    let by_name = &database().by_name;
    let name = normalize(technology);
    by_name
        .get(&name)
        .or_else(|| by_name.get(&format!("{name}js")))
        .or_else(|| name.strip_suffix("js").and_then(|bare| by_name.get(bare)))
        .copied()
}

/// One finding for each detected library whose version is in a known
/// vulnerable range.
pub fn findings(technologies: &[Technology]) -> Vec<Finding> {
    let mut seen = HashSet::new();
    technologies
        .iter()
        .filter_map(|tech| {
            let version = tech.version.as_deref()?;
            let component = component_for(&tech.name)?;
            if !seen.insert((component, version)) {
                return None;
            }
            finding_for(tech, version, component)
        })
        .collect()
}

fn finding_for(tech: &Technology, version: &str, component: &'static str) -> Option<Finding> {
    let all = database().by_component.get(component)?;
    let parsed = Version::parts_of(version)?;
    let mut matched: Vec<&Vulnerability> = all.iter().filter(|v| v.affects(&parsed, version)).collect();
    if matched.is_empty() {
        return None;
    }
    // Most serious first; the file order (by range) breaks ties.
    matched.sort_by_key(|v| std::cmp::Reverse(v.severity));
    let severity = matched[0].severity;
    let summary = matched
        .iter()
        .find(|v| v.severity == severity && !v.summary.is_empty())
        .map_or("", |v| v.summary);

    let mut identifiers: Vec<&str> = Vec::new();
    for id in matched.iter().flat_map(|v| v.identifiers.iter().copied()) {
        if !identifiers.contains(&id) {
            identifiers.push(id);
        }
    }
    const SHOWN: usize = 5;
    let ids = match identifiers.len() {
        0 => "no CVE assigned".to_owned(),
        n if n > SHOWN => format!("{} and {} more", identifiers[..SHOWN].join(", "), n - SHOWN),
        _ => identifiers.join(", "),
    };
    let fixed = first_clear_version(all, &matched).unwrap_or_else(|| "the latest release".to_owned());

    let mut evidence = format!("{} {version}", tech.name);
    // The evidence that shows the version, when one does: the first is often the
    // pattern that named the library (`jquery`), not the one with the number.
    if let Some(e) = tech
        .evidence
        .iter()
        .find(|e| e.value.contains(version))
        .or(tech.evidence.first())
    {
        let value: String = e.value.chars().take(100).collect();
        evidence.push_str(&format!(" (from {}: {value})", e.field));
    }
    let mut result = finding(
        "stack.library.vulnerable",
        &[
            ("library", tech.name.clone()),
            ("version", version.to_owned()),
            ("component", component.to_owned()),
            ("count", matched.len().to_string()),
            ("severity", format!("{severity:?}").to_ascii_lowercase()),
            ("summary", summary.trim_end_matches('.').to_owned()),
            ("ids", ids),
            ("fixed", fixed),
        ],
        evidence,
    );
    // The catalog holds a default; the severity is the worst of the matches.
    result.severity = severity;
    Some(result)
}

/// The lowest version that no known range covers, starting from the highest
/// `below` of the ranges that matched and moving up while another range still
/// covers it. Retire.js uses a `below` such as `2.999.999` for "end of life
/// line"; those are not releases and never count. `None` when no release is
/// known to be clear.
fn first_clear_version(all: &[Vulnerability], matched: &[&Vulnerability]) -> Option<String> {
    let is_release = |v: &Vulnerability| !v.below.parts.iter().any(|p| matches!(p, Part::Number(n) if *n >= 999));
    let highest = |ranges: &[&Vulnerability]| -> Option<&'static str> {
        ranges
            .iter()
            .copied()
            .filter(|v| is_release(v))
            .max_by(|a, b| a.below.cmp(&b.below))
            .map(|v| v.below.raw)
    };
    let mut candidate = highest(matched)?;
    for _ in 0..all.len() {
        let version = Version::parse(candidate)?;
        let covering: Vec<&Vulnerability> = all.iter().filter(|v| v.affects(&version, candidate)).collect();
        if covering.is_empty() {
            return Some(candidate.to_owned());
        }
        candidate = highest(&covering).filter(|next| Version::parse(next).is_some_and(|n| n > version))?;
    }
    None
}

impl Vulnerability {
    fn affects(&self, version: &Version, raw: &str) -> bool {
        self.at_or_above.as_ref().is_none_or(|low| version >= low)
            && *version < self.below
            && !self.excludes.iter().any(|e| e.eq_ignore_ascii_case(raw.trim()))
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Part {
    Number(u64),
    /// A pre-release label such as `beta`, `rc`, `alpha`, `next`.
    Tag(String),
}

/// A library version as Retire.js compares it. Split into numbers and
/// letter runs, with `.`, `-` and `_` as separators and `1.9.0b1` and
/// `1.9.0-b.1` alike. Numbers compare as numbers and a missing part is 0, so
/// `1.2` equals `1.2.0`. A label sorts before any number at the same place,
/// which puts `3.0.0-beta1` and `1.0RC2` before the release; two labels
/// compare as text, so `alpha < beta < rc`.
#[derive(Debug, Clone, Eq)]
struct Version {
    raw: &'static str,
    parts: Vec<Part>,
}

impl Version {
    /// `None` unless the text starts with a number (after an optional `v`).
    fn parse(text: &'static str) -> Option<Self> {
        let mut version = Self::parts_of(text)?;
        version.raw = text;
        Some(version)
    }

    fn parts_of(text: &str) -> Option<Self> {
        let lower = text.trim().to_ascii_lowercase();
        let body = lower.strip_prefix('v').unwrap_or(&lower);
        let body = body.split('+').next().unwrap_or_default();
        if !body.starts_with(|c: char| c.is_ascii_digit()) {
            return None;
        }
        let mut parts = Vec::new();
        let mut rest = body;
        while let Some(start) = rest.find(|c: char| c.is_ascii_alphanumeric()) {
            rest = &rest[start..];
            let digits = rest.starts_with(|c: char| c.is_ascii_digit());
            let end = rest
                .find(|c: char| c.is_ascii_digit() != digits || !c.is_ascii_alphanumeric())
                .unwrap_or(rest.len());
            let (token, tail) = rest.split_at(end);
            parts.push(if digits {
                Part::Number(token.parse().unwrap_or(u64::MAX))
            } else {
                Part::Tag(token.to_owned())
            });
            rest = tail;
        }
        Some(Self { raw: "", parts })
    }
}

impl PartialEq for Version {
    fn eq(&self, other: &Self) -> bool {
        self.cmp(other) == Ordering::Equal
    }
}

impl PartialOrd for Version {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Version {
    fn cmp(&self, other: &Self) -> Ordering {
        const ZERO: Part = Part::Number(0);
        for i in 0..self.parts.len().max(other.parts.len()) {
            let a = self.parts.get(i).unwrap_or(&ZERO);
            let b = other.parts.get(i).unwrap_or(&ZERO);
            let order = match (a, b) {
                (Part::Number(a), Part::Number(b)) => a.cmp(b),
                (Part::Number(_), Part::Tag(_)) => Ordering::Greater,
                (Part::Tag(_), Part::Number(_)) => Ordering::Less,
                (Part::Tag(a), Part::Tag(b)) => a.cmp(b),
            };
            if order != Ordering::Equal {
                return order;
            }
        }
        Ordering::Equal
    }
}

/// For the build-free check of what the data covers: the Retire.js components
/// with a vulnerability, sorted.
#[cfg(test)]
fn components() -> Vec<&'static str> {
    let mut list: Vec<&'static str> = database().by_component.keys().copied().collect();
    list.sort_unstable();
    list
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::detect::Evidence;

    fn v(text: &'static str) -> Version {
        Version::parse(text).unwrap()
    }

    fn tech(name: &str, version: Option<&str>) -> Technology {
        Technology {
            name: name.into(),
            version: version.map(str::to_owned),
            confidence: 100,
            categories: Vec::new(),
            website: None,
            evidence: vec![Evidence {
                field: "scriptSrc",
                key: None,
                value: format!("/js/{}-{}.min.js", name.to_lowercase(), version.unwrap_or("")),
            }],
            implied_by: None,
        }
    }

    #[test]
    fn versions_compare_by_number_not_text() {
        assert!(v("1.10.0") > v("1.9.9"));
        assert!(v("1.8.3") < v("1.9.0"));
        assert!(v("10.0.0") > v("9.99.99"));
        assert_eq!(v("1.2"), v("1.2.0"));
        assert_eq!(v("1.2.0.0"), v("1.2"));
        assert!(v("1.2.0.1") > v("1.2"));
        assert_eq!(v("v2.0.1"), v("2.0.1"));
        assert_eq!(v("2.0.1+build.5"), v("2.0.1"));
    }

    #[test]
    fn pre_releases_sort_before_the_release() {
        assert!(v("1.9.0b1") < v("1.9.0"));
        assert!(v("3.0.0-beta1") < v("3.0.0"));
        assert!(v("3.0.0-beta1") < v("3.0.0-rc.1"));
        assert!(v("3.0.0-rc.1") < v("3.0.0-rc.2"));
        assert!(v("3.0.0-rc.1") < v("3.0.0-rc.10"));
        assert!(v("1.0RC2") < v("1.0"));
        assert!(v("1.0.0-alpha") < v("1.0.0-beta"));
        assert!(v("1.0.0-beta") < v("1.0.0-beta.2"));
        assert!(v("2.0.0-next.3") < v("2.0.0"));
        // After the previous release, though.
        assert!(v("1.9.0b1") > v("1.8.3"));
        assert!(v("3.0.0-beta1") > v("2.2.4"));
    }

    #[test]
    fn versions_need_a_leading_number() {
        assert!(Version::parse("latest").is_none());
        assert!(Version::parse("").is_none());
        assert!(Version::parse("x.y").is_none());
        assert!(Version::parse("v1.2").is_some());
    }

    #[test]
    fn range_bounds_are_inclusive_below_and_exclusive_above() {
        let row = "lib\t1.2.1\t1.9.0\tmedium\tCVE-1\t\tx";
        let vulnerability = parse_row(row).unwrap();
        for (version, expected) in [
            ("1.2.0", false),
            ("1.2.1", true),
            ("1.8.9", true),
            ("1.9.0b1", true),
            ("1.9.0", false),
            ("1.10.0", false),
        ] {
            assert_eq!(vulnerability.affects(&v(version), version), expected, "{version}");
        }
        // No lower bound.
        let open = parse_row("lib\t\t2.0.0\tlow\t\t\t").unwrap();
        assert!(open.affects(&v("0.0.1"), "0.0.1"));
        assert!(!open.affects(&v("2.0.0"), "2.0.0"));
    }

    #[test]
    fn excluded_builds_are_not_affected() {
        let vulnerability = parse_row("jquery\t1.12.3\t3.0.0-beta1\tmedium\tCVE-2015-9251\t1.12.4-aem\tx").unwrap();
        assert!(vulnerability.affects(&v("1.12.4"), "1.12.4"));
        assert!(!vulnerability.affects(&v("1.12.4-aem"), "1.12.4-aem"));
        // A pre-release bound: 3.0.0-beta1 itself is outside, 3.0.0-alpha inside.
        assert!(!vulnerability.affects(&v("3.0.0-beta1"), "3.0.0-beta1"));
        assert!(vulnerability.affects(&v("3.0.0-alpha"), "3.0.0-alpha"));
    }

    #[test]
    fn the_data_parses_whole() {
        let rows = RETIRE.lines().filter(|l| !l.starts_with('#')).count();
        let parsed: usize = database().by_component.values().map(Vec::len).sum();
        assert!(rows > 500);
        assert_eq!(rows, parsed, "a row of data/retire.tsv did not parse");
        assert!(provenance().starts_with("RetireJS/retire.js@"), "{}", provenance());
    }

    #[test]
    fn names_map_to_components() {
        for (name, component) in [
            ("jQuery", "jquery"),
            ("jQuery UI", "jquery-ui"),
            ("jQuery Mobile", "jquery-mobile"),
            ("jQuery Migrate", "jquery-migrate"),
            ("Bootstrap", "bootstrap"),
            ("AngularJS", "angularjs"),
            ("Angular", "@angular/core"),
            ("Moment.js", "moment.js"),
            ("Lodash", "lodash"),
            ("Handlebars", "handlebars"),
            ("Vue.js", "vue"),
            ("React", "react"),
            ("Next.js", "nextjs"),
            ("Prototype", "prototypejs"),
            ("Mustache", "mustache.js"),
            ("Underscore.js", "underscore.js"),
            ("VideoJS", "video.js"),
            ("TinyMCE", "tinyMCE"),
            ("Highlight.js", "highlightjs"),
            ("DataTables", "jquery.datatables"),
            ("Knockout.js", "knockout"),
        ] {
            assert_eq!(component_for(name), Some(component), "{name}");
        }
        assert_eq!(component_for("WordPress"), None);
        assert_eq!(component_for("Next.js App Router"), None);
        assert_eq!(component_for("React Router"), None);
        assert_eq!(component_for("Angular Material"), None);
    }

    #[test]
    fn aliases_point_at_components_in_the_data() {
        let known = components();
        for (name, component) in ALIASES {
            assert!(known.contains(component), "{name}: no `{component}` in the data");
        }
    }

    #[test]
    fn jquery_1_8_3_is_flagged_with_its_cves() {
        let found = findings(&[tech("jQuery", Some("1.8.3")), tech("Nginx", Some("1.25.3"))]);
        assert_eq!(found.len(), 1);
        let f = &found[0];
        assert_eq!(f.id, "stack.library.vulnerable");
        assert_eq!(f.severity, Severity::Medium);
        assert_eq!(f.params["library"], "jQuery");
        assert_eq!(f.params["version"], "1.8.3");
        for cve in ["CVE-2012-6708", "CVE-2019-11358", "CVE-2020-11023"] {
            assert!(f.params["ids"].contains(cve), "{cve} missing in {}", f.params["ids"]);
        }
        // Fixed in 3.5.0: the CVEs of 2020 are the last ones to fall.
        assert_eq!(f.params["fixed"], "3.5.0");
        assert!(
            f.evidence.starts_with("jQuery 1.8.3 (from scriptSrc:"),
            "{}",
            f.evidence
        );
        assert!(f.title.contains("jQuery 1.8.3"));
        assert!(
            !f.detail.contains('{') && !f.fix.contains('{'),
            "{} / {}",
            f.detail,
            f.fix
        );
    }

    #[test]
    fn current_versions_and_unversioned_technologies_are_not_flagged() {
        assert!(findings(&[tech("jQuery", Some("3.7.1"))]).is_empty());
        assert!(findings(&[tech("jQuery", None)]).is_empty());
        assert!(findings(&[tech("jQuery", Some("not-a-version"))]).is_empty());
        assert!(findings(&[tech("WordPress", Some("1.0.0"))]).is_empty());
    }

    #[test]
    fn identifiers_are_capped_and_severity_is_the_worst() {
        // Bootstrap 3.0.0 has several issues, and so does AngularJS 1.0.0.
        let found = findings(&[tech("AngularJS", Some("1.0.0"))]);
        let f = &found[0];
        assert!(
            matches!(f.severity, Severity::High | Severity::Critical),
            "{:?}",
            f.severity
        );
        assert!(f.params["ids"].contains(" more"), "{}", f.params["ids"]);
        assert_eq!(
            f.params["ids"].split(" and ").next().unwrap().split(", ").count(),
            5,
            "{}",
            f.params["ids"]
        );
    }

    #[test]
    fn the_end_of_life_range_is_never_a_fix() {
        // jQuery 2.2.4 is inside the `below 2.999.999` end-of-life range, but the fix
        // is a real release.
        let found = findings(&[tech("jQuery", Some("2.2.4"))]);
        assert_eq!(found[0].params["fixed"], "3.5.0");
    }

    #[test]
    fn one_finding_for_each_library_and_version() {
        let found = findings(&[tech("jQuery", Some("1.8.3")), tech("jQuery", Some("1.8.3"))]);
        assert_eq!(found.len(), 1);
        let two = findings(&[tech("jQuery", Some("1.8.3")), tech("jQuery", Some("1.7.2"))]);
        assert_eq!(two.len(), 2);
    }

    #[test]
    fn the_analysis_reads_the_page_and_finds_the_library() {
        use crate::analyze::{content, infra, stack};
        let body = r#"<!doctype html><html lang="en"><head><title>Old site</title>
            <script src="/assets/js/jquery-1.8.3.min.js"></script></head><body><h1>Hi</h1></body></html>"#;
        let snapshot = infra::tests::snapshot_with(200, &[("content-type", "text/html")], body);
        let content = content::content(&snapshot);
        let module = stack::analyze(&snapshot, &content);
        let jquery = module
            .data
            .as_ref()
            .unwrap()
            .technologies
            .iter()
            .find(|t| t.name == "jQuery")
            .expect("jQuery is detected");
        assert_eq!(jquery.version.as_deref(), Some("1.8.3"));
        let f = module
            .findings
            .iter()
            .find(|f| f.id == "stack.library.vulnerable")
            .expect("the vulnerable library is flagged");
        assert!(f.params["ids"].contains("CVE-2012-6708"), "{:?}", f.params);
        // The evidence shows where the version was read, not just the library's name.
        assert_eq!(f.evidence.matches("1.8.3").count(), 2, "{}", f.evidence);
    }
}
